"""Everything specific to Odoo: compose file, odoo.conf, database parameters, readiness, versions and editions."""
import base64
import configparser
import hashlib
import re
import secrets
import time
import urllib.error
import urllib.request

from . import instances, settings
from .shell import capture, succeeds

COMPOSE_TEMPLATE = """\
# Generated by Odoo Instance Manager. Values come from the .env file next to this one.
# Odoo is reachable on 127.0.0.1 only; visitors come through the Odoo Instance Manager gateway.
name: odoo-{name}

services:
  db:
    image: {postgres_image}
    restart: unless-stopped
    environment:
      POSTGRES_USER: odoo
      POSTGRES_PASSWORD: ${{DB_PASSWORD}}
      POSTGRES_DB: postgres
    volumes:
      - db-data:/var/lib/postgresql/data

  odoo:
    image: {odoo_image}:${{ODOO_VERSION}}
    restart: unless-stopped
    depends_on:
      - db
    ports:
      - "127.0.0.1:${{ODOO_PORT}}:8069"
    environment:
      HOST: db
      USER: odoo
      PASSWORD: ${{DB_PASSWORD}}
    volumes:
      - odoo-data:/var/lib/odoo
      - ./config:/etc/odoo
      - ./addons:{custom_mount}
{enterprise_volume}
volumes:
  db-data:
  odoo-data:
"""


def compose_file(name, version, enterprise):
    """Contents of the instance's docker-compose.yml."""
    enterprise_volume = (f"      - {settings.ENTERPRISE_DIR / version}:{settings.ENTERPRISE_ADDONS_MOUNT}:ro\n"
                         if enterprise else "")
    return COMPOSE_TEMPLATE.format(name=name, postgres_image=settings.POSTGRES_IMAGE,
                                   odoo_image=settings.ODOO_IMAGE, custom_mount=settings.CUSTOM_ADDONS_MOUNT,
                                   enterprise_volume=enterprise_volume)


def hash_master_password(password, rounds=600_000):
    """Odoo's own format for a hashed master password (passlib pbkdf2_sha512), so odoo.conf never holds it readable.

    Odoo checks `admin_passwd` with passlib, which accepts `$pbkdf2-sha512$<rounds>$<salt>$<hash>` with both parts
    in passlib's base64 alphabet ('.' instead of '+', no padding).
    """
    def ab64(raw):
        return base64.b64encode(raw).decode().replace("+", ".").rstrip("=")
    salt = secrets.token_bytes(16)
    digest = hashlib.pbkdf2_hmac("sha512", password.encode(), salt, rounds)
    return f"$pbkdf2-sha512${rounds}${ab64(salt)}${ab64(digest)}"


def write_config(name, db, db_password, master_password):
    """Write config/odoo.conf for a new instance. The master password is stored as a hash only."""
    conf = configparser.RawConfigParser()
    conf["options"] = {
        "data_dir": "/var/lib/odoo",
        "admin_passwd": hash_master_password(master_password),
        "db_host": "db",
        "db_port": "5432",
        "db_user": "odoo",
        "db_password": db_password,
        # all interfaces inside the container, so Docker's port mapping reaches Odoo (Odoo 20 would otherwise
        # listen on the container's own 127.0.0.1); outside, the port is published on the server's 127.0.0.1
        "http_interface": "0.0.0.0",
        "dbfilter": f"^{re.escape(db)}$",
        "list_db": "False",
        "proxy_mode": "True",
    }
    with open(instances.config_file(name), "w") as fh:
        conf.write(fh)


def read_config(name):
    conf = configparser.RawConfigParser()
    conf.read(instances.config_file(name))
    return conf


def set_addons_path(name, paths):
    """Write `addons_path` into odoo.conf; return the new value."""
    conf = read_config(name)
    value = ",".join(paths)
    conf.set("options", "addons_path", value)
    with open(instances.config_file(name), "w") as fh:
        conf.write(fh)
    return value


def run_cmd(name, *args):
    """Command that runs `odoo <args>` once in a temporary container of the instance (database must be up)."""
    return instances.compose(name, "run", "--rm", "--no-deps", "-T", "odoo", "odoo", *args)


def databases(name):
    return [db for db in instances.read_env(name).get("DB_NAME", "").split(",") if db]


def wait_for_database(name, timeout=30):
    """Wait until the instance's PostgreSQL accepts connections."""
    deadline = time.time() + timeout
    while time.time() < deadline:
        if succeeds(["docker", "exec", instances.container(name, "db"), "pg_isready", "-q", "-U", "odoo"]):
            return True
        time.sleep(1)
    return False


def parameter_sql(params):
    """SQL that sets Odoo system parameters (ir.config_parameter)."""
    statements = []
    for key, value in params.items():
        quoted = value.replace("'", "''")
        statements.append("INSERT INTO ir_config_parameter (key, value, create_date, write_date) "
                          f"VALUES ('{key}', '{quoted}', now(), now()) "
                          "ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, write_date = now();")
    return "".join(statements)


def public_address_cmds(name, url):
    """Commands that tell each database of the instance its public address.

    web.base.url is used by Odoo for links in e-mails, the portal, payment and webhook URLs; it is frozen so Odoo
    does not replace it with the address an administrator logs in from. report.url makes PDF reports load their
    styles from Odoo itself instead of through the public address.
    """
    sql = parameter_sql({"web.base.url": url, "web.base.url.freeze": "True", "report.url": "http://localhost:8069"})
    return [["docker", "exec", instances.container(name, "db"), "psql", "-q", "-U", "odoo", "-d", db, "-c", sql]
            for db in databases(name)]


def responds(port, timeout=2):
    """True when Odoo answers HTTP on 127.0.0.1:<port> (any status code means it is up)."""
    try:
        urllib.request.urlopen(f"http://127.0.0.1:{port}/web/health", timeout=timeout)
        return True
    except urllib.error.HTTPError:
        return True
    except (urllib.error.URLError, OSError):
        return False


def wait_until_ready(port, timeout=240):
    deadline = time.time() + timeout
    while time.time() < deadline:
        if responds(port):
            return True
        time.sleep(3)
    return False


def recent_log(name, lines=300):
    return capture(instances.compose(name, "logs", "--no-color", "--tail", str(lines), "odoo"), timeout=30)


# --------------------------------------------------------------------------- versions and editions

_PUBLISHED_CACHE = {}


def version_published(version):
    """True when Docker Hub has the official image odoo:<version>. Cached for 10 minutes."""
    cached = _PUBLISHED_CACHE.get(version)
    if cached and time.time() - cached[1] < 600:
        return cached[0]
    try:
        urllib.request.urlopen(f"https://hub.docker.com/v2/repositories/library/odoo/tags/{version}", timeout=6)
        published = True
    except (urllib.error.URLError, OSError):
        published = False
    _PUBLISHED_CACHE[version] = (published, time.time())
    return published


def enterprise_available(version):
    """True when the Enterprise add-ons for `version` are on the server."""
    return (settings.ENTERPRISE_DIR / version / "web_enterprise" / "__manifest__.py").exists()
